export function classifyRGB(rgb){if(!rgb||rgb.length<3||!Array.from(rgb).slice(0,3).every(Number.isFinite))return {id:0};const q=Array.from(rgb).slice(0,3).map(v=>Math.round(Math.max(0,Math.min(255,v))*128/255));const code=table[(q[0]*129+q[1])*129+q[2]];return {id:code&511,lowValueFallback:!!(code&512)};}
